  function toQuestion(row, index) {
    return { text: row[0], left: row[1], right: row[2], codeLeft: row[3], codeRight: row[4], meta: { explanation: explanations[index] || "question signal" } };
  }

  function toType(row, code, lang) {
    return {
      name: row[0],
      socioName: row[1],
      quadra: row[2],
      tagline: row[3],
      shareText: shareRows[lang]?.[code] || row[12],
      summary: {
        image: row[4],
        thinkingStyle: row[5],
        workStyle: row[6],
        communicationStyle: row[7],
        strengths: row[8],
        growth: row[9],
        difficulties: row[10],
        development: row[11],
        shortSummary: row[12]
      },
      sections: []
    };
  }

  function deepMerge(target, patch) {
    Object.entries(patch || {}).forEach(([key, value]) => {
      if (value && typeof value === "object" && !Array.isArray(value)) {
        target[key] = deepMerge(target[key] || {}, value);
      } else {
        target[key] = value;
      }
    });
    return target;
  }

  langs.forEach((lang) => {
    const content = window.APP_CONTENT?.[lang];
    if (!content) return;
    content.editorial = {
      status: "author-content-v2",
      tone: "calm, precise, human, non-diagnostic",
      nextFocus: ["human editorial reread", "function-aware question model", "live deploy QA"]
    };
    deepMerge(content.ui, uiPatch[lang]);
    deepMerge(content.ui, uiPolishPatch[lang]);
    deepMerge(content.ui, profileCommentsPatch[lang]);
    deepMerge(content.ui, safetyPatch[lang]);
    deepMerge(content.ui, messagesPatch[lang]);
    content.title = uiPatch[lang].title;
    content.description = uiPatch[lang].description;
    content.questions = questionRows[lang].map(toQuestion);
    content.types = Object.fromEntries(Object.entries(typeRows[lang]).map(([code, row]) => [code, toType(row, code, lang)]));
  });
